define(['jquery', 'local_dynamicdashboard/motion'], function($, Motion) {
    return {
        /**
         * Initialize KPI counter widget.
         * @param {jQuery} $element Root element.
         */
        init: function($element) {

            var $value = $element.find('.kpi-value');
            var currentVal = parseFloat($value.text()) || 0;

            $element.on('widget:update', function(e, data) {
                if (!data.label || !data.value) {
                    return;
                }

                var targetVal = parseFloat(data.value) || 0;

                if (Motion.shouldAnimate() && targetVal !== currentVal) {
                    animateValue($value, currentVal, targetVal, 600);
                } else {
                    $value.text(data.value);
                }

                currentVal = targetVal;
            });

            /**
             * Animate number change.
             * @param {jQuery} $el عنصر القيمة.
             * @param {number} start البداية.
             * @param {number} end النهاية.
             * @param {number} duration الزمن بالمللي ثانية.
             */
            function animateValue($el, start, end, duration) {
                var range = end - start;
                var startTime = null;

                /**
                 * Animation step.
                 * @param {DOMHighResTimeStamp} timestamp الوقت الحالي.
                 */
                function step(timestamp) {
                    if (!startTime) {
                        startTime = timestamp;
                    }

                    var progress = Math.min((timestamp - startTime) / duration, 1);
                    var eased = 1 - Math.pow(1 - progress, 2); // easeOutQuad

                    $el.text(Math.round(start + range * eased));

                    if (progress < 1) {
                        requestAnimationFrame(step);
                    }
                }

                requestAnimationFrame(step);
            }
        }
    };
});